<script setup lang="ts">
const props = defineProps<{ signup?: boolean }>()
const router = useRouter()
const form = reactive({ name: "", email: "", phone: "", password: "", confirmPassword: "" })
const error = ref("")
function submit() { error.value = props.signup ? (form.name.length < 2 ? "Informe seu nome" : form.password.length < 8 ? "A senha deve ter pelo menos 8 caracteres" : form.password !== form.confirmPassword ? "As senhas não coincidem" : "") : (!form.email || !form.password ? "Preencha email e senha" : ""); if (!error.value) { localStorage.setItem("mypet-user", form.email); router.push("/dashboard") } }
</script>
<template><section class="card auth-card"><h1>{{ signup ? 'Registrar' : 'Login' }}</h1><p class="muted" style="text-align:center">{{ signup ? 'Preencha as informações para registrar' : 'Entre já! Seu pet te espera!' }}</p><form @submit.prevent="submit"><div v-if="signup" class="field"><label>Nome</label><input v-model="form.name" placeholder="John" /></div><div class="field"><label>Email</label><input v-model="form.email" type="email" placeholder="m@example.com" /></div><div v-if="signup" class="field"><label>Telefone</label><input v-model="form.phone" placeholder="(00) 9 0000-0000" /></div><div class="field"><label>Senha</label><input v-model="form.password" type="password" placeholder="Mínimo 8 caracteres" /></div><div v-if="signup" class="field"><label>Confirmar Senha</label><input v-model="form.confirmPassword" type="password" /></div><p v-if="error" style="color:#ff9da5">{{ error }}</p><button class="button full" type="submit">{{ signup ? 'Registrar' : 'Login' }}</button></form><p class="muted" style="text-align:center;margin-bottom:0">{{ signup ? 'Já possui uma conta? ' : 'Não possui uma conta? ' }}<NuxtLink :to="signup ? '/' : '/sign-up'" style="color:#fff;text-decoration:underline">{{ signup ? 'Faça seu login' : 'Faça seu cadastro' }}</NuxtLink></p></section></template>
